import { z } from 'zod';

export const AddressSchema = z.object({
  label: z.string().min(1),
  line1: z.string().min(1),
  line2: z.string().optional(),
  city: z.string().min(1),
  state: z.string().min(1),
  postalCode: z.string().min(1),
  country: z.string().length(2),
});

export const VariantSchema = z.object({
  sku: z.string().min(1),
  size: z.string(),
  color: z.string(),
  price: z.number().nonnegative(),
  stock: z.number().int().nonnegative(),
});

export const ProductSchema = z.object({
  id: z.string(),
  name: z.string().min(1),
  description: z.string(),
  categoryId: z.string().min(1),
  pricing: z.object({
    currency: z.string().length(3),
    basePrice: z.number().positive(),
    compareAt: z.number().positive().optional(),
  }),
  addresses: z.array(AddressSchema).min(1),
  variants: z.array(VariantSchema).min(1),
  tags: z.array(z.string()),
});

export type Product = z.infer<typeof ProductSchema>;

import { zodResolver } from 'qortex-resource';
import { createResourceHooks } from 'qortex-resource-react';
import { ProductSchema } from './schema';

export const {
  useResource,
  useField,
  useFieldArray,
} = createResourceHooks((productId: string) => ({
  key: ['product', productId],
  validate: { resolver: zodResolver(ProductSchema), on: 'blur' },
  persist: { draft: true, debounce: 400 },
  mutation: { optimistic: true },
  source: {
    fetch: () => api.products.get(productId),
    save: (draft) => api.products.update(productId, draft),
  },
  onSaveSuccess: () => toast.success('Product saved'),
  onSaveError: (e) => toast.error(e.message),
}));

export function ProductEditorPage({ productId }: { productId: string }) {
  const {
    isLoading,
    isSaving,
    isChanged,
    isValid,
    error,
    save,
    resetDraft,
  } = useResource(productId);

  if (isLoading) return <p>Loading product…</p>;
  if (error) return <p role="alert">Failed to load: {String(error)}</p>;

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        save();
      }}
    >
      <header>
        <h1>Edit product</h1>
        <button type="submit" disabled={!isChanged || !isValid || isSaving}>
          {isSaving ? 'Saving…' : 'Save'}
        </button>
        <button type="button" disabled={!isChanged} onClick={resetDraft}>
          Discard
        </button>
      </header>

      <BasicsSection />
      <PricingSection />
      <AddressesSection />
      <VariantsSection />
      <TagsSection />
    </form>
  );
}

function Field({ path, label, multiline }: { path: string; label: string; multiline?: boolean }) {
  const { value, error, onChange, onBlur } = useField(path);
  const Tag = multiline ? 'textarea' : 'input';
  return (
    <label>
      {label}
      <Tag
        value={(value as string) ?? ''}
        onChange={(e: any) => onChange(e.target.value)}
        onBlur={onBlur}
      />
      {error && <span role="alert">{error}</span>}
    </label>
  );
}

function NumberField({ path, label }: { path: string; label: string }) {
  const { value, error, onChange, onBlur } = useField(path);
  return (
    <label>
      {label}
      <input
        type="number"
        value={(value as number) ?? ''}
        onChange={(e) => onChange(Number(e.target.value))}
        onBlur={onBlur}
      />
      {error && <span role="alert">{error}</span>}
    </label>
  );
}

function BasicsSection() {
  return (
    <section>
      <h2>Details</h2>
      <Field path="name" label="Name" />
      <Field path="description" label="Description" multiline />
      <Field path="categoryId" label="Category" />
    </section>
  );
}

function PricingSection() {
  return (
    <section>
      <h2>Pricing</h2>
      <Field path="pricing.currency" label="Currency" />
      <NumberField path="pricing.basePrice" label="Base price" />
      <NumberField path="pricing.compareAt" label="Compare at" />
    </section>
  );
}

function AddressesSection() {
  const { fields, append, remove } = useFieldArray('addresses');

  return (
    <section>
      <h2>Addresses</h2>
      {fields.map((row) => (
        <fieldset key={row.id}>
          <legend>Address {row.index + 1}</legend>
          <Field path={`addresses.${row.index}.label`} label="Label" />
          <Field path={`addresses.${row.index}.line1`} label="Line 1" />
          <Field path={`addresses.${row.index}.line2`} label="Line 2" />
          <Field path={`addresses.${row.index}.city`} label="City" />
          <Field path={`addresses.${row.index}.state`} label="State" />
          <Field path={`addresses.${row.index}.postalCode`} label="Postal" />
          <Field path={`addresses.${row.index}.country`} label="Country" />
          <button type="button" onClick={() => remove(row.index)}>Remove</button>
        </fieldset>
      ))}
      <button
        type="button"
        onClick={() =>
          append({
            label: 'Warehouse',
            line1: '',
            city: '',
            state: '',
            postalCode: '',
            country: 'US',
          })
        }
      >
        Add address
      </button>
    </section>
  );
}

function VariantsSection() {
  const { fields, append, remove, move } = useFieldArray('variants');

  return (
    <section>
      <h2>Variants</h2>
      {fields.map((row) => (
        <div key={row.id}>
          <Field path={`variants.${row.index}.sku`} label="SKU" />
          <Field path={`variants.${row.index}.size`} label="Size" />
          <Field path={`variants.${row.index}.color`} label="Color" />
          <NumberField path={`variants.${row.index}.price`} label="Price" />
          <NumberField path={`variants.${row.index}.stock`} label="Stock" />
          <button type="button" onClick={() => remove(row.index)}>×</button>
          {row.index > 0 && (
            <button type="button" onClick={() => move(row.index, row.index - 1)}>↑</button>
          )}
        </div>
      ))}
      <button
        type="button"
        onClick={() => append({ sku: '', size: '', color: '', price: 0, stock: 0 })}
      >
        Add variant
      </button>
    </section>
  );
}

function TagsSection() {
  const { fields, append, remove } = useFieldArray('tags');
  const [draft, setDraft] = useState('');

  return (
    <section>
      <h2>Tags</h2>
      <ul>
        {fields.map((row) => (
          <li key={row.id}>
            {String(row.item)}
            <button type="button" onClick={() => remove(row.index)}>×</button>
          </li>
        ))}
      </ul>
      <input value={draft} onChange={(e) => setDraft(e.target.value)} />
      <button
        type="button"
        onClick={() => {
          if (!draft.trim()) return;
          append(draft.trim());
          setDraft('');
        }}
      >
        Add tag
      </button>
    </section>
  );
}
